const serviceKey = 'sb_secret_b0IcObDVlfwIlKpClSJD_Q_bAAK8DxJ';
let products = [];
try {
  const res = await fetch('https://bnblofcypxfydnptazrs.supabase.co/rest/v1/products?category_id=eq.1a111111-1111-1111-1111-111111111111&is_available=eq.true&select=name_vi,price,image_url', {
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey }
  });
  products = await res.json();
} catch (e) {
  // fallback nếu mạng trục trặc
}

if (!products || !products.length) {
  products = [
    { name_vi: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI", price: 55000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252169872-e67ur3a.png" },
    { name_vi: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI", price: 70000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790257589853-gaob8nq.png" },
    { name_vi: "SANDWICH TRỨNG PHÔ MAI", price: 40000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252774417-m33tz1o.png" },
    { name_vi: "SANDWICH DĂM BÔNG PHÔ MAI MỸ", price: 50000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790317233417-b2u9a28.png" },
    { name_vi: "SANDWICH GÀ NƯỚNG PESTO", price: 60000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252411821-18oppot.png" },
    { name_vi: "SANDWICH THỊT HỘP, PHÔ MAI & NORI", price: 60000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252648517-nbn1oi2.png" },
    { name_vi: "SANDWICH THỊT XÔNG KHÓI NGÔ PHÔ MAI", price: 50000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252476216-pmpd82w.png" },
    { name_vi: "SANDWICH CÁ NGỪ PHÔ MAI", price: 60000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790252360765-ftrb245.png" },
    { name_vi: "SANDWICH NƯỚNG KIỂU PHÁP", price: 55000, image_url: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/products/1790317861516-nu32o17.png" }
  ];
}

const today = new Date();
const dayOfWeek = today.getDay();

let angle = "";
if (dayOfWeek === 1 || dayOfWeek === 3) {
  angle = "Đồng hành công sở (Bữa sáng vội vã, ăn sạch tay không dính mỡ, no lâu, gom đơn cùng đồng nghiệp)";
} else if (dayOfWeek === 2 || dayOfWeek === 4) {
  angle = "Cứu đói xế chiều 14h - 16h (Thèm phô mai kéo sợi ngập tràn, tiếp năng lượng giờ làm việc uể oải)";
} else if (dayOfWeek === 5) {
  angle = "Nạp năng lượng cuối tuần (Tự thưởng cho bản thân bữa ăn nóng hổi chất lượng chuẩn vị Seoul)";
} else {
  angle = "Dạo phố cổ Hồ Gươm (Bánh nướng nóng hổi cầm tay dạo quanh phố 54 Nguyễn Hữu Huân)";
}

const selected = products[Math.floor(Math.random() * products.length)];
const formattedPrice = Number(selected.price).toLocaleString('vi-VN') + 'đ';

return [
  {
    json: {
      dishName: selected.name_vi,
      dishPrice: formattedPrice,
      dishPriceRaw: selected.price,
      photoUrl: selected.image_url,
      targetAngle: angle,
      date: today.toLocaleDateString("vi-VN"),
      storeAddress: "54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội",
      website: "eggu.vn"
    }
  }
];

let rawText = $json.content.parts[0].text.trim();
if (rawText.startsWith('```json')) {
  rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
} else if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Bài viết Facebook EGGU',
    content: rawText,
    dish: $('Code - Kho Ảnh Thật Website & Góc Bài Viết').item.json.dishName,
    status: 'Chờ duyệt',
    created_at: new Date().toISOString()
  };
}

const dishInfo = $('Code - Kho Ảnh Thật Website & Góc Bài Viết').item.json;

return [
  {
    json: {
      title: parsed.title || ('EGGU - ' + dishInfo.dishName),
      dishName: dishInfo.dishName,
      dishPrice: dishInfo.dishPrice,
      targetAngle: dishInfo.targetAngle,
      content: parsed.content || rawText,
      realPhotoUrl: dishInfo.photoUrl,
      aiPhotoUrl: dishInfo.photoUrl,
      status: 'PENDING',
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': parsed.title || ('EGGU - ' + dishInfo.dishName),
      'Món ăn': dishInfo.dishName + ' (Giá web: ' + dishInfo.dishPrice + ')',
      'Nội dung Facebook (Đã biên tập)': parsed.content || rawText,
      '📸 ẢNH SẢN PHẨM CHÍNH HÃNG (Bao bì chuẩn EGGU 100%)': dishInfo.photoUrl,
      'Gợi ý đăng bài': 'Đăng bài kèm ảnh sản phẩm chính hãng sắc nét của quán!',
      'Trạng thái': 'Chờ nhân viên copy',
      'Thời gian tạo': new Date().toLocaleString('vi-VN')
    }
  }
];
